@st.cache_data(ttl=300,show_spinner=False)
def load_history(mtime):
    hpath=ROOT/'data'/'history.csv.gz'
    if not hpath.exists():return pd.DataFrame()
    h=pd.read_csv(hpath,dtype={'symbol':str})
    for c in ['open','high','low','close','volume']:
        h[c]=pd.to_numeric(h[c],errors='coerce')
    if not h.empty:
        dates=pd.to_datetime(h['date'],errors='coerce')
        latest=dates.max()
        if pd.notna(latest):
            h=h.loc[dates >= latest-pd.DateOffset(years=1)].copy()
    return h

def prepare_bars(rows, timeframe='日 K'):
    d=rows.copy()
    d['date']=pd.to_datetime(d['date'],errors='coerce')
    d=d.dropna(subset=['date','close']).sort_values('date').drop_duplicates('date')
    if timeframe=='週 K':
        d=(d.set_index('date').resample('W-FRI').agg({'open':'first','high':'max','low':'min','close':'last','volume':'sum'}).dropna(subset=['close']).reset_index())
        # Label weekly candles by their actual last trading day, not an untraded Friday.
        actual_dates=rows.copy()
        actual_dates['date']=pd.to_datetime(actual_dates['date'],errors='coerce')
        actual_dates=actual_dates.dropna(subset=['date']).set_index('date')
        last_dates=actual_dates.groupby(pd.Grouper(freq='W-FRI')).apply(lambda g:g.index.max() if len(g) else pd.NaT).dropna()
        d['date']=d['date'].map(dict(zip(last_dates.index,last_dates.values)))
    return d

def compute_indicators(d):
    d=d.copy();close=d.close.astype(float)
    for n in (5,10,20,60):d[f'ma{n}']=close.rolling(n,min_periods=n).mean()
    delta=close.diff();gain=delta.clip(lower=0).ewm(alpha=1/14,adjust=False,min_periods=14).mean()
    loss=(-delta.clip(upper=0)).ewm(alpha=1/14,adjust=False,min_periods=14).mean()
    d['rsi']=100-100/(1+gain/loss.replace(0,np.nan))
    d.loc[(loss==0)&(gain>0),'rsi']=100
    d['dif']=close.ewm(span=12,adjust=False,min_periods=26).mean()-close.ewm(span=26,adjust=False,min_periods=26).mean()
    d['signal']=d.dif.ewm(span=9,adjust=False,min_periods=9).mean()
    d['histogram']=d.dif-d.signal
    # Prior 20 completed periods only: avoids using today's volume in its own baseline.
    d['volume_ratio']=d.volume/d.volume.shift(1).rolling(20,min_periods=20).mean().replace(0,np.nan)
    # Prior 20 / 60 completed bars: avoid look-ahead in breakout levels.
    for n in (20,60):
        d[f'resistance{n}']=d.high.shift(1).rolling(n,min_periods=n).max()
        d[f'support{n}']=d.low.shift(1).rolling(n,min_periods=n).min()
    return d

def swing_zones(bars, left=3, right=3, lookback=125, atr_factor=.65, min_touches=2):
    """Confirmed swing zones. Pivot at i becomes usable only at i+right.

    Only historical, confirmed pivots contribute to the latest zones. Zone width
    uses a prior rolling ATR estimate, and does not require future candles.
    """
    d=bars.reset_index(drop=True).copy()
    if len(d)<left+right+3:return []
    high=pd.to_numeric(d.high,errors='coerce').to_numpy(dtype=float)
    low=pd.to_numeric(d.low,errors='coerce').to_numpy(dtype=float)
    close=pd.to_numeric(d.close,errors='coerce').to_numpy(dtype=float)
    tr=np.maximum.reduce([high-low,np.abs(high-np.r_[np.nan,close[:-1]]),np.abs(low-np.r_[np.nan,close[:-1]])])
    atr=pd.Series(tr).rolling(14,min_periods=5).mean().to_numpy()
    events=[]
    start=max(left,len(d)-lookback)
    for i in range(start,len(d)-right):
        window_high=high[i-left:i+right+1]
        window_low=low[i-left:i+right+1]
        if not np.isfinite(window_high).all() or not np.isfinite(window_low).all():continue
        # Strictly unique extrema avoid counting flat tops repeatedly.
        if high[i]==window_high.max() and np.sum(window_high==high[i])==1:
            events.append(('壓力',float(high[i]),i+right,float(atr[i]) if np.isfinite(atr[i]) else np.nan))
        if low[i]==window_low.min() and np.sum(window_low==low[i])==1:
            events.append(('支撐',float(low[i]),i+right,float(atr[i]) if np.isfinite(atr[i]) else np.nan))
    zones=[]
    for kind,price,confirmed,local_atr in events:
        width=max(price*.003,local_atr*atr_factor if np.isfinite(local_atr) else 0)
        matches=[z for z in zones if z['kind']==kind and abs(z['center']-price)<=max(z['width'],width)]
        if matches:
            z=min(matches,key=lambda z:abs(z['center']-price))
            z['prices'].append(price)
            z['center']=float(np.median(z['prices']))
            z['width']=max(z['width'],width)
            z['confirmed']=max(z['confirmed'],confirmed)
        else:
            zones.append(dict(kind=kind,center=price,width=width,prices=[price],confirmed=confirmed))
    result=[]
    for z in zones:
        if len(z['prices'])<min_touches:continue
        # Keep the region narrow; do not widen to the full day's candle.
        half=max(z['width']*.5,(max(z['prices'])-min(z['prices']))*.5)
        result.append(dict(kind=z['kind'],center=z['center'],lower=z['center']-half,
                           upper=z['center']+half,touches=len(z['prices']),confirmed=z['confirmed']))
    return sorted(result,key=lambda z:(-z['touches'],-z['confirmed']))


def zone_summary(bars, zones):
    if bars.empty:return []
    close=float(bars.close.iloc[-1]);result=[]
    for z in zones:
        if z['lower']>close:
            position='上方壓力候選';gap=(z['lower']/close-1)*100
        elif z['upper']<close:
            position='下方支撐候選';gap=(z['upper']/close-1)*100
        else:
            position='現價所在區間';gap=0.0
        result.append({**z,'position':position,'distance_pct':gap})
    return result


def history_quality_report(bars):
    if bars.empty:return ['沒有可用的歷史行情'],None
    d=bars.sort_values('date').copy();messages=[]
    for col in ('open','high','low','close','volume'):
        d[col]=pd.to_numeric(d[col],errors='coerce')
    invalid=(d[['open','high','low','close']].isna().any(axis=1) |
             (d[['open','high','low','close']]<=0).any(axis=1) |
             (d.high<d[['open','close','low']].max(axis=1)) |
             (d.low>d[['open','close','high']].min(axis=1)))
    if invalid.any():messages.append(f'OHLC 不一致或缺值：{int(invalid.sum())} 根')
    if (d.volume<0).any():messages.append('發現負成交量')
    duplicate=int(d.date.duplicated().sum())
    if duplicate:messages.append(f'重複交易日期：{duplicate} 筆')
    spikes=int((d.close.pct_change(fill_method=None).abs()>.30).sum())
    if spikes:messages.append(f'單日收盤變動超過 30%：{spikes} 筆，請確認公司行動或還原價格')
    if pd.to_datetime(d.date,errors='coerce').isna().any():messages.append('存在無法解析的交易日期')
    return messages,dict(first=str(d.date.iloc[0])[:10],last=str(d.date.iloc[-1])[:10],count=len(d))


def candle_figure(rows,title,count=90,timeframe='日 K'):
    d=compute_indicators(prepare_bars(rows,timeframe)).tail(count)
    x=d.date.dt.strftime('%Y-%m-%d')
    fig=go.Figure()
    fig.add_trace(go.Candlestick(x=x,open=d.open,high=d.high,low=d.low,close=d.close,
        increasing_line_color='#f16d7b',decreasing_line_color='#19c6a1',name='K'))
    fig.add_trace(go.Scatter(x=x,y=d.ma20,name='MA20',mode='lines',line=dict(color='#f6c15e',width=1.4)))
    fig.update_layout(title=dict(text=title,font=dict(size=13)),height=290,margin=dict(l=7,r=7,t=35,b=10),
        template='plotly_dark',paper_bgcolor='#101a28',plot_bgcolor='#101a28',font=dict(color='#b8cadc',size=10),
        xaxis_rangeslider_visible=False,showlegend=False,dragmode='pan',uirevision=f'{title}_{timeframe}',
        xaxis=dict(type='category',nticks=6,showgrid=False),yaxis=dict(showgrid=True,gridcolor='#243348'))
    return fig

def linked_figure(rows,title,count=90,timeframe='日 K',ma_periods=(20,),show_volume=True,
                  show_rsi=True,show_macd=True,show_levels=False,show_ratio=True,expanded=False,
                  level_mode='最新水平線',show_pivot_zones=False):
    full_bars=prepare_bars(rows,timeframe)
    zones=swing_zones(full_bars) if show_pivot_zones else []
    d=compute_indicators(full_bars)
    d=d.tail(count).copy()
    panes=['K']+(['成交量'] if show_volume else [])+(['RSI'] if show_rsi else [])+(['MACD'] if show_macd else [])
    # Dynamically redistribute space when any indicator panel is hidden.
    weights=[5.5]+[1.5]*(len(panes)-1)
    total=sum(weights);heights=[v/total for v in weights]
    fig=make_subplots(rows=len(panes),cols=1,shared_xaxes=True,vertical_spacing=.025,row_heights=heights)
    x=d.date.dt.strftime('%Y-%m-%d')
    fig.add_trace(go.Candlestick(x=x,open=d.open,high=d.high,low=d.low,close=d.close,
        increasing_line_color='#f16d7b',decreasing_line_color='#19c6a1',name=timeframe),row=1,col=1)
    colors={5:'#70c7f5',10:'#b58aff',20:'#f6c15e',60:'#f17c91'}
    for n in ma_periods:
        if d[f'ma{n}'].notna().any():
            fig.add_trace(go.Scatter(x=x,y=d[f'ma{n}'],name=f'MA{n}',mode='lines',line=dict(color=colors[n],width=1.5)),row=1,col=1)
    if show_levels:
        # Prior completed bars only. Use the latest non-null level for current reference lines.
        level_info=[]
        for n,color in [(20,'#f1aa65'),(60,'#a28ff0')]:
            for field,dash in [('resistance','dash'),('support','dot')]:
                col=f'{field}{n}'
                valid=d[col].dropna()
                if valid.empty:
                    continue
                last=float(valid.iloc[-1])
                label=f'{"R" if field=="resistance" else "S"}{n}'
                if level_mode=='歷史動態線':
                    fig.add_trace(go.Scatter(x=x,y=d[col],name=f'{label} 歷史',mode='lines',
                        line=dict(color=color,width=1.3,dash=dash),opacity=.78,
                        hovertemplate='%{x}<br>%{y:,.2f}<extra>%{fullData.name}</extra>'),row=1,col=1)
                else:
                    fig.add_hline(y=last,line_dash=dash,line_color=color,line_width=1.4,
                                  opacity=.88,row=1,col=1)
                level_info.append((label,last,color))
        # Offset near-overlapping labels in pixel space, while anchoring the line itself to its exact price.
        # xref=paper makes labels visible in the right-hand margin, even for S20 close to S60.
        level_info.sort(key=lambda t:t[1])
        offsets={}
        for idx,(label,price,color) in enumerate(level_info):
            offsets[label]=(-13 if idx%2==0 else 13) if any(
                abs(price-other)<max(1,price*.012) for j,(_,other,_) in enumerate(level_info) if j!=idx
            ) else 0
        for label,price,color in level_info:
            fig.add_annotation(x=1.005,y=price,xref='paper',yref='y',
                text=f'{label} {price:,.2f}',xanchor='left',yanchor='middle',
                yshift=offsets[label],showarrow=False,
                font=dict(color=color,size=10),bgcolor='#101a28',bordercolor=color,borderwidth=.5)

    if show_pivot_zones and zones and not d.empty:
        summarized=zone_summary(d,zones)
        chosen=[]
        for position in ('上方壓力候選','下方支撐候選','現價所在區間'):
            matches=sorted((z for z in summarized if z['position']==position),
                           key=lambda z:(abs(z['distance_pct']),-z['touches']))
            chosen.extend(matches[:2])
        for z in chosen:
            color=('#e9a75c' if z['position']=='上方壓力候選'
                   else '#4bd1af' if z['position']=='下方支撐候選'
                   else '#a58bf0')
            fig.add_hrect(y0=z['lower'],y1=z['upper'],fillcolor=color,opacity=.15,
                          line_width=0,row=1,col=1)

    row=2
    if show_volume:
        fig.add_trace(go.Bar(x=x,y=d.volume,name='成交量',marker_color='#5b91bb'),row=row,col=1)
        if show_ratio and d.volume_ratio.notna().any():
            latest_ratio=d.volume_ratio.dropna().iloc[-1]
            fig.add_annotation(text=f'最新量比 {latest_ratio:.2f}×',xref='paper',yref='paper',x=.99,y=.96,
                               showarrow=False,font=dict(color='#f6c15e',size=11),bgcolor='#101a28')
        row+=1
    if show_rsi:
        fig.add_trace(go.Scatter(x=x,y=d.rsi,name='RSI(14)',line=dict(color='#f6c15e',width=1.5)),row=row,col=1)
        fig.add_hline(y=70,line_dash='dot',line_color='#e66b78',row=row,col=1)
        fig.add_hline(y=30,line_dash='dot',line_color='#2bc7a2',row=row,col=1)
        fig.update_yaxes(range=[0,100],row=row,col=1);row+=1
    if show_macd:
        fig.add_trace(go.Bar(x=x,y=d.histogram,name='MACD 柱',marker_color='#5b91bb'),row=row,col=1)
        fig.add_trace(go.Scatter(x=x,y=d.dif,name='DIF',line=dict(color='#2bc7a2',width=1.4)),row=row,col=1)
        fig.add_trace(go.Scatter(x=x,y=d.signal,name='Signal',line=dict(color='#f6c15e',width=1.4)),row=row,col=1)
    fig.update_layout(title=dict(text=title,font=dict(size=14)),height=(450 if expanded else 360)+max(0,len(panes)-1)*(175 if expanded else 145),
        margin=dict(l=12,r=112 if show_levels else 25,t=55,b=28),template='plotly_dark',paper_bgcolor='#101a28',plot_bgcolor='#101a28',
        font=dict(color='#b8cadc',size=10),xaxis_rangeslider_visible=False,showlegend=True,
        legend=dict(orientation='h',y=1.03,x=0),dragmode='pan',hovermode='x unified',
        uirevision=f'{title}_{timeframe}_{count}_{expanded}')
    fig.update_xaxes(type='category',nticks=9,showgrid=False,showspikes=True,spikemode='across',spikesnap='cursor',spikecolor='#b5c6d8',spikethickness=1)
    fig.update_yaxes(gridcolor='#243348')
    return fig

